WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (127::BIGINT, 'Se pasa fácil es cuestión de tener buen grupo de trabajo las clases son muyy aburridas y largas, no usa Tec digital, instrucciones no claras. Le da por llamar gente al azar para preguntarle algo a ver si ponen atención y eso lo evalua, al ser tan aburrida lo dificulta... Fuera de eso se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'd14ee4b61fe438203ee1755f8962f76c0775ae4d05149e97edfe54103d1fde84'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'No fue profe mio pero en una conferencia del seminario que fui que él estaba me pareció una falta de respeto que forzara a las personas a participar de la nada acercándoles el micrófono diciendo que "él podía leer mentes" y se enojaba cuando alguien no tenía nada que decir. Totalmente no profesional'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-01T00:00:00+00:00'::TIMESTAMPTZ, '145cb33455334090e741badf7958277421e94b4b2de1620229d4780cb1f509a1'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Deja unos videos para hacer reportes sobre ellos, trata de hacer la clase menos aburrida y que el curso sea más fácil con el formato de los exámenes, en las presentaciones suele explicar cosas que ya se dijeron de otra forma para que los demás entiendan, haciendo que uno parezca equivocado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, '6537c591410868330dd97c663aa6269d8dfcc91a88887f48f6c8d4ab3f4dc626'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'Las instrucciones suelen ser ambiguas, el curso se pasa con asistir, hacer los informe y presentaciones, en las presentaciones interrumpe mucho para agregar información, hay que estar atento en clase porque suele preguntar opiniones sobre lo que está explicando Incita al uso de las IA con conciencia'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'd728351fc976782a2cd4c81e07b530fb4aa3664817679b9fffa486b36ca9a7e3'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Excelente profe, sus clases son muy fáciles en general. El curso en sí es algo aburrido pero él intenta que la clase sea entretenida. Casi no usa TEC Digital pero los aspectos de evaluación siguen siendo claros. Los exámenes son muy fáciles. No deja muchas tareas a excepción de reportes de videos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f7b9a7cd53258823c931fda8e407db1dc9044a4a00b2e42cae2c8c30610cc55c'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'Evite a este señor, no enfoca para nada el curso a ética, solo habla de sus opiniones de IA y política. Interrumpe las exposiciones de los estudiantes, las evaluaciones son un desorden, no usa TEC Digital, hace preguntas sorpresa y se enoja si no presta atención.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '7f833225966b9b24f7d89c31bb131210e3a439c2c1f7a3b4ed15ba3d538159bc'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Curso muy fácil y si lo quiere pasar con +95 llévelo con él. Pero va a desear cada día que llegue semana 16 para dejar de ir. El profe habla de temas como bombas atómicas y conflictos políticos, pero espera que uno sepa lo mismo que el. Se molesta si uno no participa, aunque no sepa nada del tema'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-04-04T00:00:00+00:00'::TIMESTAMPTZ, '39e3301698351603425acd61367c15415d5b09f81b293461937d1a619ef95931'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Es buen profe, pero las clases son muy aburridas y demaciado largas, usa cada minuto que dura la clase, no le gusta que se use el celular en clases.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2024-08-16T00:00:00+00:00'::TIMESTAMPTZ, '9eb97bca4e19f2487df1095426a31d46e8372a6365c8e14ea66f207b030ea8a9'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Es un adulto mayor, muy buena persona y ayuda bastante, un poco lento para la tecnología, pero se pasa muy bien si se cumple con lo que el pide. En lo personal saque 100 y teniendo trabajos en grupo (que es en lo que se basan las clases).'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '714199c557c79b5bbe306df971e3563db48588e5dcbee7ae915ac1a87971bea9'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Es un señor mayor, entonces no sabe utilizar el etc digital y teams. Las clases las termina dando uno y siempre hay que prestar atencion por que el le pregunta a quien sea y cuando sea. Sinceramente es un curso regalado'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '9c97636b794278a9177d634759896fd6f28ca79b4dd2ec0f41425e249a4ee08b'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El profe es un desastre. No sabe usar teams y mucho menos el Tec digital. Las instrucciones para los trabajos son cero claras y el profe no ayuda mucho que digamos. Si usted es de los que se estresan mucho con estas cosas no lo lleve con él. Sin embargo el curso es regalado.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'caddee8051e46ec4a65b9938c3d93df8036beea39cbff62d1895eb881f31ca01'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El curso se pasa easy, debe hacer 6 informes(3 individuales y 3 grupales ), 3 presentaciones grupales y también da puntos por participación y asistencia, las clases son aburridisimas pero nada más ponga un poco de atención y listo, en general el curso prácticamente ni lo sentí.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-10T00:00:00+00:00'::TIMESTAMPTZ, '4d611b0d5d6c6d051d2589f738aad4f55c497b79383d0a4fc8a4f03904b21f2e'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Va a hacer 3 reportes individuales de vídeos de 2-3hrs aprox, 3 reportes grupales y 3 exposiciones grupales (40min 5 participantes). Las clases son largas y aburridas, difíciles de prestar atención. Va a pasar fácil, aunque no con buena nota.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa', 'Clases largas']::TEXT[], '2023-11-27T00:00:00+00:00'::TIMESTAMPTZ, '6b803a4d724d00ca35acd1dd72c5a2696044a21df0da874e2c28e599eb26b2b7'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'En modalidad semipresencial (que 14 clases fueron virtales) , son 2 créditos regalados , nada más ponga atención en clase y conteste lo que el le pregunte, literalmente yo hacía los bretes un día antes de la entrega y pase chilling.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5585307125db2739074346a794309c91a40cc3c18f9a08b702e66d8754751f53'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Demasiado desorganizado, tiene que participar y piner atencion, su forma de hablar puede confundir.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fe31517876fb65e9d62107017cb724057b45887f832838b676cf4dfb4c58aab3'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Si quiere llevar el seminario solo por meter créditos extra no lo meta con él, deja trabajos que son fáciles pero si quitan tiempo. Hay presentaciones todas las semanas y su aprendizaje depende de cuánto le interesen las presentaciones de sus compañeros. Evaluación confusa, califica participación.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7702eee81be99cf386efa6e97e6ee3bca849ea918187f9adca9da22680ab1829'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'La materia es llevadera, es bastante facil el curso, solo hacer lo que dice y ya, nada del otro mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'ecf8f9600e8dfa4837101448cb73ba407444d5de73d3456305e37615367cb8ed'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El profe cae bastante bien, es muy conocedor de muchos temas y realmente es interesante escucharlo, sin embargo puede llegar a ser aburrido porque habla con un tono un toque bajo y monótono. Es un poco desorganizado también, casi nunca era muy claro, pero en general es un profesor bastante decente.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Brinda apoyo']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'df27b12bc20ba853e2de96e8bdac91a55cbcf136fbf63c07df6b8f4e63975a29'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Muy buen profesor, las clases pueden ser aburridad ya sea por la tónica del curso y por la manera de ser del profe, pero es muy buena persona. Hay que participar mucho y prestar bastante atención a las clases y exposiciones grupales.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-05-30T00:00:00+00:00'::TIMESTAMPTZ, '75e271d207b3545eac91caa4caf23287e3e6e071946ccbaf8690aed294856b5d'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'No se le puede llevar la contraria, hay que participar en todas las clases y en todos los trabajos individuales pone la misma calificación, se pasa fácil si se llevan los trabajos al día'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-14T00:00:00+00:00'::TIMESTAMPTZ, '19ce987a7a494b442990dc4166aeba934ad7c6e39c333b56ea4946f9bba905f3'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Las tareas son super faciles, ademas que hay muchas clases asincronicas y la mayoria de clases sincronicas es ver exposiciones grupales. Se pasa facil el curso y el profesor es super buena nota'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Pocos exámenes']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f65f7915663bb4a320773a393a374b6d660d274f99b1686a8ae3ecfeebaf3d37'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'El profe es súper bueno, hace varios trabajos pero nada de otro mundo, sabe muchisimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, '62c83fefee53e800dec0bef911e0daa1fc61d1e80212f64b83f942aadfb5a148'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'A veces él puede ser un poco aburrido. Pero trata temas muy interesantes y uno aprende mucho (en especial de física de nuclear). Deja ciertos trabajos que hace que los 2 créditos sí se sientan. No son díficiles en lo absoluto pero no te va a regalar el curso. Él es muy comprensivo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '6d6c493f54b9382c5679eda75f4867e022df8d9067b00f90dad856f1abce66be'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Es un muy buen profesor, es paciente y ayuda al estudiante. Sus clases son muy dinámicas y es interesante escucharlo. De fijo lleven los seminarios con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-26T00:00:00+00:00'::TIMESTAMPTZ, '436313c9824a136ee2ad52d25ee06ae0650317d96a84fb92cceb6b7ea2fae270'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Un profe excelente Importante: cuenta la participación'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ff18af1df701738e05a0f7a1656911ee95246f08ce1fb14dd62aeaf5aa87eb62'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Lo recomiendo si usted es alguien que le gusta participar, pues parte de la calificación es asistencia y participación, sino le gusta nada de eso mejor busque otro porque a veces da estrés que le pregunte algo y tal vez no puso atención que obvio afecta la nota. Una teja de persona pero aburrido'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '5d599215c4c33ce54dad879d75ef23bd5a9323d9cb8e21d565027364393c026e'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El profe es una teja. Sabe demasiado y es muy amable. Toma muy en cuenta la participación. De lo mejor que tiene la escuela junto a Jorge Prendas y Oscar Rodriguez.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-04-05T00:00:00+00:00'::TIMESTAMPTZ, '0819ea41070e9a5fbd4ba62568a5df7e0b881f55a0420f57ddc569ff6bf4da9e'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El profe es demasiado buena gente y sabe mucho; además, sabe transmitir ese conocimiento. Deja 3 presentaciones grupales, 3 reportes grupales y 3 individuales que no toman mucho tiempo, sin examen, se pasa súper fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'ac8a4e76d5ce21ca3b808336e2fbcf10ef60103f0d782b1aca9eb228c61a009a'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Lo lleve de forma virtual, son tres presentaciones grupales, tres reportes grupales y tres individuales, la asistencia cuenta ya que no realiza examen. Un curso lindo pero si requiere de tiempo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'c7f6726cda07ad8583583b375e99002c769dd87c99ab89828be20943e33f3deb'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'El profe sabe demasiado, las clases son bastante interesantes. Se hacen 3 presentaciones grupales y 3 reportes de documentales o películas. Si entrega todo probablemente tenga mas de 90 en el curso. Es muy buena opción.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '82520cfc2f9254963629d43cdf6c1d47a96c7402cb87060c51919fac46857f5b'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Sabe demasiado, a veces es realmente interesante escucharlo hablar sobre temas nucleares aunque la clase se puede volver muy larga. Deja pocos trabajos, unas cuantas presentaciones (sin cámara), y unas películas para ver. Saber aprovechar las clases virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, 'ca420004ee3495b87cce6c91e4e63b42f676cc148da486c2fe20602d8765ff25'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Las clases son largas por lo que suelen ser aburridas. Deja muchos reportes grupales, pero si los hace se pasa facil con 90 el curso.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'f213f42baebcb99c386330411709264702e2b90aef2a2986e953cd0d62d55cdd'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Este profe es una excelente persona, el curso se pasa solo con ir y cumplir con los reportes(virtual).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'dda3cf4680cf58cccc190d90432e11756a102ca5a90a6aa9483972c09b585514'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '6822307042430d5dbd0d850fdca9ac9f61183f38d47e72233e56272b3d960101'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Orienta el curso hacia el lado tecnologico lo cual esta muy bien, sin embargo aveces se vuelve un poco aburrido. Sabe mucho de todos los temas, pero si uno debate ideas no suele aceptar que uno tiene razon. De evaluacion no hizo examenes, solo exposicion y ensayos en cada clase.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Pocos exámenes']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4fc8d57fbf4ff66066c1db9e4d8df547139d001aadc16a4b7e14311943e12c2f'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Extremadamente aburrido. Su comentario cuenta si va con el pensamiento qu el tiene si no está malo. Es demasiado desordenado con los trabajos y demasiado confuso con la calificaión.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'caaca09495b6ffc200b5bb8a82a517a3a01612a8a73f7129e85d1fc7f68c84d3'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Aburridísimo, señala al estudiante para que conteste las preguntas que sólo él entiende... la clase se hace eterna. Pasa lista a las 7:25 am prácticamente y es super desordenado'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'ee0edf7d7f8c3856dd6ad41fbe7ad47b3ebbce8996bfef1c94a68e548e3cdebc'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a0d86cd051cf4a4b38a6792fd310b2665fcf0fc0d8558399ef5a540ae6344ea5'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ab3afa121cbb39278c5d862a36d494a2f7b8eabc36c898f40baf498c197ac6df'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'Demasiado buen profe, sabe mucho y se nota que está enterado de lo que pasa actualmente en CR!! Super paciente también. Lo llevaria otra vez.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-03-08T00:00:00+00:00'::TIMESTAMPTZ, '36c68d302d4375a3b6d6efc3e0537b06644e8838bd500a7d6f7d65bbd3c4693e'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'a1a5265f3a7c2b4d146619fcf7d22fd026e7bdd2164bc27a347dc6aa8d7a35a3'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-21T00:00:00+00:00'::TIMESTAMPTZ, '43579e7976b67ad4424e7a39c5f64686a7298ed3f90a10f5ae6ab5ca5e042f39'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'El curso es fácil. Solo que concuerdo en que no acepta una posición contraria. Muy estricto con las ausencias, y es muuuuy desordenado, al punto que pierde exámenes y trabajos finales! Matricule solo si no queda de otra Nota: Mezcla los seminarios de ética y filosóficos a conveniencia (desorden)'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '182fbbc2e9a1a574b7dfe7be4718f8c53be2987360957f97e86222deab984d0d'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Excelente persona, humilde y sencillo. Sabe muchísimo en bastantes temas, le gusta el interés por parte de sus estudiantes. Es un poco desordenado con los exámenes y fechas, pero pasable. Le gusta la creatividad y el análisis crítico de parte de uno.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2015-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'e603b7e05f353a0f42d4db136c32dde19d297021bb77255f21edd289f8f25bca'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Simplemente es un señor con el que no se puede discutir, si ud opina diferente a el se enoja y si en una discusión ud le va ganando, cambia de tema y al final no acepta su opinión. Además pierde mucho tiempo en analisis de casos en los cuales pone mala nota si ud no llega a la respuesta que el quier'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-28T00:00:00+00:00'::TIMESTAMPTZ, '749465ecc8a15a3a9861e452abd05f05ba7f355729b3014e48f078c839ed8032'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '419b95c6e126de5f04e845a6766fd16f54f2f7322102db6a48a1ccb5b5bb67ef'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '964b44de9f8778ae22b7c74bd1e2043eb8be32bcefd17f4e36b94361fc2b08bb'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'Conoce de cualquier tema, no recarga el curso con muchos trabajos sino que lo hace más dinámico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '128e5cd800e67ff2d35d12248bf42525c25845ecddc2d01013ddec66df22f0b0'::TEXT, ARRAY[559]::BIGINT[]),
    (127::BIGINT, 'Simplemente don Celso es un erudito, puede hablar de cualquier tema que se quiera'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '153f9957ec3220d549de917639eee23523e2e66a2fc9b45d162886996d088d91'::TEXT, ARRAY[981]::BIGINT[]),
    (127::BIGINT, 'Buen profesor, explica bien, el nivel de trabajo que deja sí es bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '56a541725ac8fad43d45ca7f67bb3711f009f0d683f5c8faae7b86c30fe636ce'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'pesimo, tras de que no se aprende nada, deja un condenado juego de roles que lo unico que hace es hacer que uno pierda tiempo a lo loco'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4af2936bff44a90401c7607b22c68120fac155a80e9621894702f207ec9369b3'::TEXT, ARRAY[980]::BIGINT[]),
    (127::BIGINT, 'El sabe mucho sin embargo aveces se desvía mucho del tema y deja muchos trabajos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'fa2e39c9a8abc72ca89ebde6f33e9f2a51f836399a790dbbb2c5d23bfcd122bf'::TEXT, ARRAY[980]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
